function CardArt(rank, suit) {
    var leftSide, rightSide;
    if (rank === "10") { leftSide = "10"; rightSide = suit; }
    else                { leftSide = rank + " "; rightSide = " " + suit; }
    return [
        "+-----+",
        "|" + leftSide + "  |",
        "|  " + suit + "  |",
        "|  " + rightSide + "|",
        "+-----+"
    ].join("\n");
}

function CardArtLarge(rank, suit) {
    var rankStr = rank;
    while (rankStr.length < 2) rankStr += " ";
    var suitStr = " " + suit + " ";
    return [
        "+===========+",
        "|" + rankStr + "         |",
        "|           |",
        "|           |",
        "|" + suitStr + "    |",
        "|           |",
        "|           |",
        "|         " + rankStr + "|",
        "+===========+"
    ].join("\n");
}

