function Pad(input, width, padChar) {
    var pad = padChar;
    if (pad === undefined) pad = " ";
    var s = "" + input;
    while (s.length < width) s = pad + s;
    return s;
}

function PadCenter(input, width) {
    var s = "" + input;
    var total = width - s.length;
    var left = Math.floor(total / 2);
    var right = total - left;
    return Pad("", left, " ") + s + Pad("", right, " ");
}

function Clamp(value, min, max) {
    if (value < min) return min;
    if (value > max) return max;
    return value;
}

function PrintLn(line) {
    if (typeof WScript === "undefined") return;
    try { if (WScript.StdOut) { WScript.StdOut.WriteLine(line); return; } } catch(e) { try { if (typeof WScript.Echo === "function") { WScript.Echo(line); return; } } catch(e2) {} }
    if (typeof console !== "undefined") console.log(line);
}

function Print(line) {
    if (typeof WScript === "undefined") return;
    try { if (WScript.StdOut) { WScript.StdOut.Write(line); return; } } catch(e) { try { if (typeof WScript.Echo === "function") { WScript.Echo(line); return; } } catch(e2) {} }
    if (typeof console !== "undefined") console.log(line);
}

function ReadLine(prompt) {
    if (typeof WScript === "undefined") return "";
    try { if (WScript.StdOut) WScript.StdOut.Write(prompt); else if (typeof WScript.Echo === "function") WScript.Echo(prompt); } catch(e) {}
    try { if (WScript.StdIn) { var __line = WScript.StdIn.ReadLine(); return (__line === null || __line === undefined) ? "" : ("" + __line); } } catch(e) {}
    return "";
}

function ClearScreen() {
    if (typeof WScript !== "undefined" && WScript.StdOut) {
        WScript.StdOut.WriteLine("");
    }
    PrintLn("");
}

function Pause(ms) {
    if (typeof WScript !== "undefined" && WScript.Sleep) WScript.Sleep(ms);
}

function GetSuitColor(suitIndex) {
    return SUIT_COLORS_ARRAY[suitIndex];
}

function CardToString(cardValue, hideCard) {
    if (hideCard) return "[??]";
    var rank = Math.floor(cardValue / 4);
    var suit = cardValue % 4;
    return RANKS_ARRAY[rank] + SUIT_SYMBOLS_ARRAY[suit];
}

function CardFromIndex(idx) {
    return { rank: Math.floor(idx / 4), suit: idx % 4, value: idx };
}

function HandValue(handArr) {
    var total = 0;
    var aces = 0;
    for (var i = 0; i < handArr.length; i++) {
        var rank = Math.floor(handArr[i] / 4);
        total += RANK_VALUES_HARD[rank];
        if (rank === 0) aces++;
    }
    while (total > 21 && aces > 0) { total -= 10; aces--; }
    return total;
}

function HandIsSoft(handArr) {
    var total = 0;
    var aces = 0;
    for (var i = 0; i < handArr.length; i++) {
        var rank = Math.floor(handArr[i] / 4);
        total += RANK_VALUES_HARD[rank];
        if (rank === 0) aces++;
    }
    while (total > 21 && aces > 0) { total -= 10; aces--; }
    return (aces > 0);
}

function HandIsBlackjack(handArr) {
    return handArr.length === 2 && HandValue(handArr) === 21;
}

function HandIsBust(handArr) {
    return HandValue(handArr) > 21;
}

function HandIsPair(handArr) {
    if (handArr.length !== 2) return false;
    var r1 = Math.floor(handArr[0] / 4);
    var r2 = Math.floor(handArr[1] / 4);
    return r1 === r2;
}

function PrintHand(handArr, hideFirst, label) {
    var display = label ? label + ": " : "";
    for (var i = 0; i < handArr.length; i++) {
        if (i === 0 && hideFirst) display += "[??]  ";
        else                       display += CardToString(handArr[i]) + "  ";
    }
    if (!hideFirst) display += "  (Total: " + HandValue(handArr) + ")";
    PrintLn(display);
}

function BuildShoe(numDecks) {
    var shoe = [];
    for (var d = 0; d < numDecks; d++) {
        for (var c = 0; c < 52; c++) shoe.push(c);
    }
    return shoe;
}

function Shuffle(arr) {
    var i = arr.length - 1;
    var j, tmp;
    while (i > 0) {
        j = Math.floor(Math.random() * (i + 1));
        tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
        i--;
    }
    return arr;
}

function Cut() {
    var cutPoint = Math.floor(SHOE_DECK.length * CUT_CARD_POSITION);
    var top = SHOE_DECK.slice(0, cutPoint);
    var bottom = SHOE_DECK.slice(cutPoint);
    SHOE_DECK = bottom.concat(top);
}

