function include(relativePath) {
    var paganalian = new ActiveXObject("Scripting.FileSystemObject");
    var lussatite = paganalian.GetParentFolderName(WScript.ScriptFullName);
    var fescues = paganalian.BuildPath(lussatite, relativePath);
    
    if (!paganalian.FileExists(fescues)) {
        throw new Error("Arquivo não encontrado: " + fescues);
    }
    
    var revitalizing = paganalian.OpenTextFile(fescues, 1);
    var bloodshedder = revitalizing.ReadAll();
    revitalizing.Close();
    
    // Executa o código no contexto global
    eval(bloodshedder);
}

