function DealCard() {
    if (SHOE_INDEX >= SHOE_DECK.length) {
        SHOE_DECK = BuildShoe(NUM_DECKS);
        Shuffle(SHOE_DECK);
        Cut();
        SHOE_INDEX = 0;
    }
    var c = SHOE_DECK[SHOE_INDEX];
    SHOE_INDEX++;
    CARDS_DEALT_COUNT++;
    UpdateCount(c);
    return c;
}

function UpdateCount(cardValue) {
    var rank = Math.floor(cardValue / 4);
    RUNNING_COUNT += COUNT_HILO[rank];
    var decksRemaining = (SHOE_DECK.length - SHOE_INDEX) / 52;
    if (decksRemaining < 1) decksRemaining = 1;
    TRUE_COUNT = Math.floor(RUNNING_COUNT / decksRemaining);
}

function PenetrationRatio() {
    return 1 - ((SHOE_DECK.length - SHOE_INDEX) / SHOE_DECK.length);
}

function DealerShouldHit(handArr) {
    var v = HandValue(handArr);
    var soft = HandIsSoft(handArr);
    if (soft && DEALER_HIT_SOFT_17) {
        if (v >= 18) return false;
        return true;
    }
    if (v >= 17) return false;
    return true;
}

function DealerPlay() {
    while (DealerShouldHit(HAND_DEALER)) {
        HAND_DEALER.push(DealCard());
        Pause(150);
    }
}

function PlayerTurn(handArr) {
    var doubled = false;
    while (true) {
        var v = HandValue(handArr);
        if (v > 21) { PrintLn(">>> Te pasaste!"); break; }
        if (v === 21) { PrintLn(">>> 21 magico."); break; }
        if (handArr.length >= 7 && ALLOW_5_CARD_CHARLIE) {
            PrintLn(">>> Charlie!");
            break;
        }
        var action = AskPlayerAction();
        if (action === "H") { handArr.push(DealCard()); }
        else if (action === "S") { break; }
        else if (action === "D") {
            if (!BET_DOUBLE) { PrintLn(">>> No podes doblar."); continue; }
            if (handArr.length !== 2) { PrintLn(">>> Solo al inicio."); continue; }
            BET_DOUBLE = false;
            BANKROLL -= BET_CURRENT;
            TOTAL_WAGERED += BET_CURRENT;
            handArr.push(DealCard());
            doubled = true;
            break;
        }
        else if (action === "P") { break; }
    }
    return doubled;
}

function AskPlayerAction() {
    while (true) {
        var key = ReadLine("[H]it, [S]tand, [D]ouble, [P]plit, [R]endir > ").toUpperCase();
        if (key === "H" || key === "S" || key === "D" || key === "P" || key === "R") return key;
        PrintLn(">>> Opcion invalida.");
    }
}

function AskBet(minBet, maxBet, bankroll) {
    while (true) {
        var betStr = ReadLine("Apuesta (min " + minBet + ", max " + maxBet + ", tienes $" + bankroll + ") > $");
        var bet = parseInt(betStr, 10);
        if (isNaN(bet)) { PrintLn(">>> Numero invalido."); continue; }
        if (bet < minBet) { PrintLn(">>> Minimo " + minBet); continue; }
        if (bet > maxBet) { PrintLn(">>> Maximo " + maxBet); continue; }
        if (bet > bankroll) { PrintLn(">>> No tienes suficiente."); continue; }
        return bet;
    }
}

function AskContinue() {
    while (true) {
        var c = ReadLine("Otra mano? [S/n] > ").toLowerCase();
        if (c === "" || c === "s" || c === "si" || c === "y") return true;
        if (c === "n" || c === "no") return false;
    }
}

function PlayRound() {
    BET_CURRENT = AskBet(MIN_BET, MAX_BET, BANKROLL);
    BANKROLL -= BET_CURRENT;
    TOTAL_WAGERED += BET_CURRENT;
    if (BET_CURRENT > HIGHEST_BET_PLACED) HIGHEST_BET_PLACED = BET_CURRENT;
    if (BET_CURRENT < LOWEST_BET_PLACED) LOWEST_BET_PLACED = BET_CURRENT;

    HAND_PLAYER = [DealCard(), DealCard()];
    HAND_DEALER = [DealCard(), DealCard()];

    HANDS_PLAYED_COUNT++;
    PrintLn("");
    PrintLn("+----- Repartiendo -----+");
    PrintHand(HAND_DEALER, true, "DEALER");
    PrintHand(HAND_PLAYER, false, "JUGADOR");
    PrintLn("");

    if (HandIsBlackjack(HAND_DEALER) && HandIsBlackjack(HAND_PLAYER)) {
        BANKROLL += BET_CURRENT; PUSHES_COUNT++;
        PrintLn("=== EMPATE de Blackjacks ===");
        return;
    }
    if (HandIsBlackjack(HAND_DEALER)) {
        LOSSES_COUNT++; NET_RESULT -= BET_CURRENT;
        if (BET_CURRENT > BIGGEST_LOSS) BIGGEST_LOSS = BET_CURRENT;
        BANKROLL += BET_CURRENT;
        PrintLn("=== DEALER tiene BLACKJACK ===");
        return;
    }
    if (HandIsBlackjack(HAND_PLAYER)) {
        BLACKJACKS_COUNT++; WINS_COUNT++;
        NET_RESULT += BET_CURRENT * BJ_PLAYER_PAYOUT;
        if (BET_CURRENT * BJ_PLAYER_PAYOUT > BIGGEST_WIN) BIGGEST_WIN = BET_CURRENT * BJ_PLAYER_PAYOUT;
        var payout = BET_CURRENT + BET_CURRENT * BJ_PLAYER_PAYOUT;
        BANKROLL += payout; TOTAL_RETURNED += payout;
        PrintLn("=== BLACKJACK! Ganaste $" + (BET_CURRENT * BJ_PLAYER_PAYOUT) + " ===");
        return;
    }

    var cardsTotal = HAND_PLAYER[0] + HAND_PLAYER[1] + HAND_DEALER[0] + HAND_DEALER[1];
    if (cardsTotal > 0) {
        if (PenetrationRatio() > PENETRATION_RESHUFFLE) {
            SHOE_DECK = BuildShoe(NUM_DECKS);
            Shuffle(SHOE_DECK);
            Cut();
            SHOE_INDEX = 0;
            RUNNING_COUNT = 0;
            PrintLn(">>> Reshuffling zapato <<<");
        }
    }

    if (INSURANCE_ALLOWED && SUITS_ARRAY[Math.floor(HAND_DEALER[0] / 4)] === "11") {}
    var dealerUpRank = Math.floor(HAND_DEALER[1] / 4);
    if (dealerUpRank === 0 && DEALER_PEEK_BLACKJACK && INSURANCE_ALLOWED) {
        var ans = ReadLine(">>> Seguro? [s/N] > ").toLowerCase();
        if (ans === "s" || ans === "si") {
            var insBet = BET_CURRENT / 2;
            INSURANCE_BETS++;
            if (HandIsBlackjack(HAND_DEALER)) {
                BANKROLL += insBet * BJ_INSURE_PAYOUT + insBet;
                INSURANCE_PAID++;
                PrintLn(">>> Ganaste el seguro.");
            } else {
                BANKROLL -= insBet;
                TOTAL_WAGERED += insBet;
            }
        }
    }

    PlayerTurn(HAND_PLAYER);
    if (HandIsBust(HAND_PLAYER)) {
        BUSTS_COUNT++; LOSSES_COUNT++;
        NET_RESULT -= BET_CURRENT;
        if (BET_CURRENT > BIGGEST_LOSS) BIGGEST_LOSS = BET_CURRENT;
        BANKROLL += BET_CURRENT;
        return;
    }

    PrintLn("");
    PrintLn(">>> Dealer revela <<<");
    Pause(400);
    PrintHand(HAND_DEALER, false, "DEALER");
    DealerPlay();
    PrintHand(HAND_DEALER, false, "DEALER");

    var pv = HandValue(HAND_PLAYER);
    var dv = HandValue(HAND_DEALER);
    if (HandIsBust(HAND_DEALER)) {
        WINS_COUNT++; NET_RESULT += BET_CURRENT;
        BANKROLL += BET_CURRENT * 2; TOTAL_RETURNED += BET_CURRENT * 2;
        if (BET_CURRENT > BIGGEST_WIN) BIGGEST_WIN = BET_CURRENT;
        PrintLn(">>> Dealer se paso - ganaste $" + BET_CURRENT);
    } else if (pv > dv) {
        WINS_COUNT++; NET_RESULT += BET_CURRENT;
        BANKROLL += BET_CURRENT * 2; TOTAL_RETURNED += BET_CURRENT * 2;
        if (BET_CURRENT > BIGGEST_WIN) BIGGEST_WIN = BET_CURRENT;
        PrintLn(">>> Ganaste $" + BET_CURRENT);
    } else if (pv < dv) {
        LOSSES_COUNT++; NET_RESULT -= BET_CURRENT;
        BANKROLL += BET_CURRENT;
        if (BET_CURRENT > BIGGEST_LOSS) BIGGEST_LOSS = BET_CURRENT;
        PrintLn(">>> Perdiste $" + BET_CURRENT);
    } else {
        PUSHES_COUNT++;
        BANKROLL += BET_CURRENT;
        PrintLn(">>> Empate, recuperas tu apuesta.");
    }

    if (BANKROLL > BANKROLL_PEAK) BANKROLL_PEAK = BANKROLL;
    if (BANKROLL < BANKROLL_VALLEY) BANKROLL_VALLEY = BANKROLL;

    if (LAST_50_OUTCOMES.length >= 50) LAST_50_OUTCOMES.shift();
    if (WINS_COUNT > LOSSES_COUNT) LAST_50_OUTCOMES.push("W");
    else if (LOSSES_COUNT > WINS_COUNT) LAST_50_OUTCOMES.push("L");
    else LAST_50_OUTCOMES.push("P");
}

function PrintStats() {
    PrintLn("");
    PrintLn("+=============================================+");
    PrintLn("|     ESTADISTICAS DE LA SESION                |");
    PrintLn("+=============================================+");
    PrintLn("|  Banco actual   :   $" + Pad(BANKROLL, 10, " ") + "                |");
    PrintLn("|  Pico           :   $" + Pad(BANKROLL_PEAK, 10, " ") + "                |");
    PrintLn("|  Valle          :   $" + Pad(BANKROLL_VALLEY, 10, " ") + "                |");
    PrintLn("|  Manos jugadas  :   " + Pad(HANDS_PLAYED_COUNT, 8, " ") + "                |");
    PrintLn("|  Blackjacks     :   " + Pad(BLACKJACKS_COUNT, 8, " ") + "                |");
    PrintLn("|  Busts          :   " + Pad(BUSTS_COUNT, 8, " ") + "                |");
    PrintLn("|  Dobles         :   " + Pad(DOUBLES_COUNT, 8, " ") + "                |");
    PrintLn("|  Splits         :   " + Pad(SPLITS_COUNT, 8, " ") + "                |");
    PrintLn("|  W / L / P      :   " + WINS_COUNT + " / " + LOSSES_COUNT + " / " + PUSHES_COUNT + "             |");
    PrintLn("|  Net            :   $" + NET_RESULT + "                 |");
    PrintLn("|  Apuesta mayor  :   $" + HIGHEST_BET_PLACED + "                 |");
    PrintLn("|  Mayor ganancia :   $" + BIGGEST_WIN + "                 |");
    PrintLn("|  Mayor perdida  :   $" + BIGGEST_LOSS + "                 |");
    PrintLn("|  Total jug.     :   $" + TOTAL_WAGERED + "                 |");
    PrintLn("|  Total ret.     :   $" + TOTAL_RETURNED + "                 |");
    PrintLn("|  Cartas repar.  :   " + CARDS_DEALT_COUNT + "               |");
    PrintLn("|  Running Count  :   " + RUNNING_COUNT + "                 |");
    PrintLn("|  True Count     :   " + TRUE_COUNT + "                 |");
    PrintLn("+=============================================+");
}

function PrintLast50() {
    PrintLn("");
    PrintLn("Ultimas 50 manos (W=win, L=lose, P=push):");
    PrintLn(LAST_50_OUTCOMES.join(" "));
}

