function MainMenu() {
    while (true) {
        PrintLn("");
        PrintLn("1. Jugar");
        PrintLn("2. Ver reglas");
        PrintLn("3. Ver estrategia");
        PrintLn("4. Ver variantes");
        PrintLn("5. Estadisticas");
        PrintLn("6. Cambiar reglas (reset)");
        PrintLn("7. Salir");
        var opt = ReadLine("> ");
        if (opt === "1") return "PLAY";
        if (opt === "2") { ShowRules(); continue; }
        if (opt === "3") { ShowStrategy(); continue; }
        if (opt === "4") { ShowVariants(); continue; }
        if (opt === "5") { PrintStats(); PrintLast50(); continue; }
        if (opt === "6") { ResetGame(); continue; }
        if (opt === "7") return "EXIT";
    }
}

function ResetGame() {
    BANKROLL = STARTING_BANKROLL;
    BANKROLL_PEAK = STARTING_BANKROLL;
    BANKROLL_VALLEY = STARTING_BANKROLL;
    HANDS_PLAYED_COUNT = 0;
    BLACKJACKS_COUNT = 0;
    BUSTS_COUNT = 0;
    DOUBLES_COUNT = 0;
    SPLITS_COUNT = 0;
    WINS_COUNT = 0;
    LOSSES_COUNT = 0;
    PUSHES_COUNT = 0;
    NET_RESULT = 0;
    TOTAL_WAGERED = 0;
    TOTAL_RETURNED = 0;
    LAST_50_OUTCOMES = [];
    RUNNING_COUNT = 0;
    PrintLn(">>> Banco reseteado a $" + STARTING_BANKROLL);
}

function Main() {
    if (typeof WScript === "undefined" || !WScript.StdIn) {
        PrintLn("Ejecutar con: cscript juego1_blackjack.js");
        return;
    }

    ShowBanner();

    SHOE_DECK = BuildShoe(NUM_DECKS);
    Shuffle(SHOE_DECK);
    Cut();

    while (true) {
        var action = MainMenu();
        if (action === "EXIT") break;
        if (action === "PLAY") {
            PlayRound();
            if (BANKROLL < MIN_BET) {
                PrintLn(">>> Te quedaste sin pasta. Banca rota.");
                break;
            }
        }
    }

    PrintLn("");
    PrintLn("=== Fin de la sesion ===");
    PrintStats();
    PrintLast50();
    PrintLn("");
}

